# exec()'d from build.py. seo_more(path, body) returns an extra <section> of genuinely useful guide text
# so that every indexable page carries 700+ words. Wording is varied per page (hash-picked variants) and
# only uses facts already on the site (prices, durations, samagri, languages, festivals).
import hashlib,re as _re
TARGET=780
def _A():return globals().get('AREAS') or []
def _h(s,n):return int(hashlib.md5(s.encode()).hexdigest(),16)%n
def _wc(h):
    h=_re.sub(r'(?s)<(script|style|noscript|svg|select|aside).*?</\1>','',h)
    return len(_re.sub(r'<[^>]+>',' ',h).split())
def _pick(key,*v):return v[_h(key,len(v))]
def _pl(x):return ", ".join(f'<a href="{s[0]}.html">{s[1]}</a>' for s in x)
SKIP=("404.html",)

def V(k,i,*a):return a[_h(k+str(i),len(a))]
def _order(k,items):
    return sorted(items,key=lambda t:_h(k+t[0][:12],997))
def _sections_city(path,c):
    city,state,areas,sup,fest,note,hub=c["city"],c["state"],c["areas"],c["sup"],c["fest"],c["note"],c["hub"]
    lo=min(x[5] for x in S);hi=max(x[5] for x in S);k=path;top=S[:6]
    pj=[S[(_h(k,len(S))+n)%len(S)] for n in range(6)]
    first=[(f"Why families in {city} book a pandit online",
      "<p>"+V(k,1,f"Finding a reliable pandit in {city} usually means asking relatives and calling several numbers, and still being unsure about the muhurat.",f"When a housewarming, a naming ceremony or an annual puja is coming up in {city}, the hardest part is rarely the ritual; it is finding a pandit who is free on your date.",f"Many families in {city} tell us the real difficulty is not the puja itself but finding the right pandit at short notice.",f"Arranging a puja in {city} often starts with a round of phone calls to relatives and neighbours.")+" "+V(k,2,"Online Pujari replaces that search with one request: tell us the puja, the date and your language.","We handle the coordination: share your requirement once and we come back with a named pandit and a muhurat.","You give us the puja, the date and the language you prefer, and we do the matching.")+" "+V(k,3,f"We confirm the pandit and an auspicious time for {city} on WhatsApp before you pay anything.",f"Nothing is charged until the pandit and muhurat for {city} are confirmed on WhatsApp.",f"Payment is taken only after the plan for {city} is confirmed with you in writing.")+"</p><p>"+V(k,4,"This helps new homeowners, young couples performing a first puja, and families living away from elders who usually arrange these things.","It is especially useful when elders are far away and you are arranging a puja for the first time.","First-time hosts in particular value having the puja name, timing, samagri list and price written down clearly.")+"</p>"),
     (f"Pujas families in {city} book most often","<p>"+V(k,5,"The pujas below are the ones families ask for most.","These are the pujas most commonly requested.","Here are popular choices, each with its purpose, usual duration and starting price.")+" "+V(k,6,"Each page explains the purpose, samagri and duration so you can decide before booking.","Open any page to see samagri, timing and what is included.","Every page lists what the ritual needs and what it costs.")+"</p><ul>"+"".join(f'<li><a href="{s[0]}.html"><b>{s[1]}</b></a>: {s[7]} Typically {s[6]}, from ₹{s[5]:,}.</li>' for s in pj)+f"</ul><p>{V(k,7,'We also arrange','Beyond these we arrange','Other options include')} {_pl(S[:3]+S[-3:])} {V(k,8,'and other sanskar. If your puja is not listed, choose “Other puja” in the booking form and describe it.','and more. If you do not see yours, pick “Other puja” and tell us what you need.')}</p>")]
    mid=[(f"Choosing the right muhurat in {city}","<p>"+V(k,9,"A muhurat is the auspicious window chosen from tithi, nakshatra, weekday and your family’s Panchang tradition.","The muhurat combines the tithi, nakshatra and weekday with the almanac your family follows.","Auspicious timing is not only about the date but also the hour, and it comes from the Panchang.")+" "+V(k,10,f"Sunrise and sunset differ between cities, so for {city} we check timings for {city} itself instead of a national table.",f"Local sunrise shifts the timings from one city to another, so we confirm the muhurat for {city} specifically.",f"We calculate the muhurat for {city} rather than copying a generic calendar, because local timings differ.")+"</p><p>"+V(k,11,"Already have a date from your family priest? Tell us and we will confirm it. If not, choose “help me find a date” and share days that suit you.","Share any date your family has in mind; if there is none, give us a range of days and we suggest the best ones.","If you have no date yet, send a few days that work and we will recommend the most suitable muhurat.")+" "+V(k,12,"Weekends and festival weeks fill quickly, so ask at least a week ahead.","Book a week early, and earlier during wedding season or Diwali.","Popular weekend slots go first, so do not wait until the last week.")+"</p>"),
     (f"Venue planning: home, apartment, society or office","<p>"+V(k,13,f"Most pujas in {city} happen in a flat, an independent house, a society hall, an office or a shop.",f"In {city} a puja may be held at home, in an apartment complex, at a community hall, or at an office or shop.","The venue shapes the planning more than people expect.")+"</p><ul>"+"".join(V(k,20+n,*alts) for n,alts in enumerate([("<li><b>Apartments and societies:</b> ask the resident association whether a havan or open flame is allowed and whether guests need gate passes.</li>","<li><b>Flats:</b> check society rules on havan smoke, lift use for the samagri and visitor entry.</li>"),("<li><b>Independent homes:</b> clear a clean, level space facing the direction your pandit suggests, usually east or north.</li>","<li><b>Houses:</b> keep a tidy, level corner ready, commonly facing east or north.</li>"),("<li><b>Offices and shops:</b> pick a time outside peak hours so staff and customers are not disturbed.</li>","<li><b>Business premises:</b> early morning or after closing usually works best.</li>"),("<li><b>Access:</b> share the floor, landmark and parking details so the pandit arrives on time with the kit.</li>","<li><b>Directions:</b> send a map pin and parking details so the pandit can reach you on time.</li>")]))+"</ul><p>"+(f"We arrange pandits across {city}, including {areas}, subject to availability on your date." if areas else f"We arrange pandits across {city} and nearby towns, subject to availability on your date.")+"</p>"),
     ("Samagri: bring your own or let the pandit arrange it","<p>"+V(k,30,"Samagri means the materials used in the puja: flowers, fruits, ghee, camphor, a kalash and havan items.","Samagri is the set of items a puja needs, from flowers and fruit to ghee, camphor and havan material.")+" "+V(k,31,"Our puja pages list what each ritual needs, and you can choose to collect it yourself or take the “with samagri” option.","You may gather the items yourself or choose a complete kit brought by the pandit.","Families short on time usually take the kit and buy only fresh flowers and fruit.")+f" {V(k,32,f'Perishables such as flowers and mango leaves are best bought on the morning of the puja in {city}.',f'Buy flowers, banana leaves and fruit locally in {city} on the day for freshness.')}</p>"),
     (f"Languages and traditions in {city}",f"<p>{note} "+V(k,33,"We match pandits by language and tradition first.","Language and sampradaya come first when we match a pandit.")+f" For {city} we offer {', '.join(sup)}"+(f", and {c['reg']}-speaking pandits can be arranged on request" if c.get('reg') and c['reg'] not in sup else "")+". "+V(k,34,"Telling us your family’s sampradaya, kulachar or gotra helps the pandit prepare the sankalp correctly.","Please share your gotra and family custom at booking so the sankalp is accurate.")+"</p>")]
    if fest:mid.append((f"Festivals and occasions in {state}",f"<p>"+V(k,35,f"Families in {state} commonly plan pujas around {fest}.",f"The busiest weeks for pandits in {state} are around {fest}.",f"Around {fest}, demand for pandits across {state} rises sharply.")+" "+V(k,36,"Many also schedule a satyanarayan katha, rudrabhishek or sundarkand path nearby.","Share your date early so we can hold a slot.","Book early if your date sits in a festival week.")+" Our <a href=\"festival-calendar-2026.html\">festival calendar</a> lists dates to plan around.</p>"))
    mid+= [(f"Online puja for families who live outside {city}","<p>"+V(k,37,f"If you live abroad or in another city but want a puja performed for your family in {city}, a video puja is possible.",f"A pandit can lead a puja for you by video if you cannot be in {city} on the day.")+" "+V(k,38,"The pandit performs the sankalp in your name and gotra, explains each step and shares prasad details afterwards.","You follow along live, and the sankalp is taken in your name and gotra.")+" "+V(k,39,"It is popular for parents’ shraddh, birthday homams and festival pujas.","Families use it for shraddh, homams and festival pujas when travel is hard.")+"</p>"),
     (f"What it costs to book a pandit in {city}",f"<p>"+V(k,40,f"Pujas start from ₹{lo:,} and larger ceremonies go up to ₹{hi:,} or more.",f"Prices begin at ₹{lo:,}; bigger ceremonies can reach ₹{hi:,} or more.")+" "+V(k,41,"The final amount depends on the ritual, duration, number of pandits and the samagri kit, and is confirmed before you pay.","Each puja page shows prices with and without the kit, and the total is confirmed on WhatsApp first.")+" "+V(k,42,"Dakshina and guest hospitality are separate and up to you.","Dakshina for the pandit is at your discretion.")+"</p>"),
     (f"Checklist before the pandit arrives in {city}","<ol class='steps'>"+"".join(V(k,50+n,*alts) for n,alts in enumerate([("<li>Confirm the date, muhurat and arrival time on WhatsApp.</li>","<li>Re-check the muhurat and timing a day before.</li>"),("<li>Clean the puja space and keep a low seat or mat ready.</li>","<li>Tidy the space and arrange a mat or low seat.</li>"),("<li>Collect samagri or confirm the kit; keep fresh flowers and fruit.</li>","<li>Arrange the samagri and buy fresh flowers and fruit.</li>"),("<li>Keep the family’s names and gotra ready for the sankalp.</li>","<li>Note each participant’s name and gotra.</li>"),("<li>Inform neighbours or society staff if there will be a havan.</li>","<li>Tell society staff if a havan is planned.</li>"),("<li>Keep prasad, water and a place for the pandit to rest.</li>","<li>Arrange prasad and drinking water.</li>")]))+"</ol>")]
    last=[(f"More cities in {state}",f"<p>Explore pandit booking across <a href=\"{hub}\">{state}</a> or browse <a href=\"locations.html\">all cities we serve</a>. You can also read our <a href=\"puja-glossary.html\">puja glossary</a> to understand common terms before you speak to a pandit.</p>")]
    return first+_order(k,mid)+last

def _sections_state(path,c):
    state,cs,sup,fest,note=c["state"],c["cs"],c["sup"],c["fest"],c["note"]
    names=", ".join(x[1] for x in cs)
    lo=min(x[5] for x in S);hi=max(x[5] for x in S)
    return [
    (f"Booking a pandit in {state}",f"<p>{note} Online Pujari brings that variety into one place: you choose your city in {state}, the puja and the language, and we confirm a pandit and muhurat on WhatsApp before you pay. We currently list pandit booking for {len(cs)} {'city' if len(cs)==1 else 'cities'} in {state}: {names}. If your town is not listed, message us anyway; we often arrange pandits in nearby towns or an online puja.</p>"),
    (f"Languages and traditions in {state}",f"<p>We offer pandits who perform puja in {', '.join(sup)}"+(f", and {c['reg']}-speaking pandits can be arranged on request" if c['reg'] not in sup else "")+". Language matters for more than conversation: the mantras, the explanation of each step and the family customs all feel more meaningful when the pandit speaks the way your household does. Please mention your sampradaya or family tradition when you book so the pandit prepares the correct sankalp and sequence.</p>"),
    (f"Festivals and occasions in {state}",f"<p>The busiest times for pandits in {state} are around {fest}. During these weeks many families book a satyanarayan katha, a rudrabhishek, a lakshmi puja or a sundarkand path, and slots fill early. If your date is close to a festival, book at least two weeks ahead. Our <a href=\"festival-calendar-2026.html\">festival calendar</a> and <a href=\"blog.html\">blog</a> explain dates and rules.</p>"),
    (f"Popular pujas families book in {state}","<ul>"+"".join(f'<li><a href="{s[0]}.html"><b>{s[1]}</b></a>: {s[3]} Typically {s[6]}, from ₹{s[5]:,}.</li>' for s in S[:8])+"</ul>"),
    ("How the muhurat is chosen",f"<p>Auspicious timings depend on the tithi, nakshatra, weekday and the local sunrise, which shifts across {state}. Instead of copying one calendar for the whole state, we confirm the muhurat for your own city and your family’s Panchang tradition. If you do not have a date, share a few days that suit you and we will suggest the best options.</p>"),
    (f"Home, apartment and office pujas in {state}","<p>Pujas happen in flats, independent houses, society halls, temples, offices and shops. For apartments check whether a havan is allowed, how the samagri can be carried in and whether guests need gate passes. For shops and offices pick a time outside peak hours. Share your address, floor and parking details so the pandit arrives on time.</p>"),
    ("Samagri and the cost of a puja",f"<p>Pujas start from ₹{lo:,} and larger ceremonies go up to ₹{hi:,} or more depending on the ritual, duration and number of pandits. Each puja page shows prices with and without the samagri kit. The total is confirmed before you pay; dakshina and guest hospitality are separate and up to you.</p>"),
    ("Online puja from anywhere",f"<p>If you live outside {state}, or a pandit in your language is not free on your date, a pandit can lead the puja by video and perform the sankalp in your name and gotra. This is popular for festival pujas, birthday homams and shraddh when families cannot travel home.</p>"),
    ("Frequently asked questions",f"<h3>Are pandits verified?</h3><p>Yes. We speak to every pandit before listing them and confirm the muhurat and plan with you before payment.</p><h3>Do I pay in advance?</h3><p>You pay only after the pandit and muhurat are confirmed.</p><h3>Can I choose the language?</h3><p>Yes. Pick it in the form, and we match accordingly.</p><h3>What if my city is not listed?</h3><p>Message us on WhatsApp. We may have a pandit nearby or can arrange an online puja.</p>")]

def _sections_puja(path,s):
    slug,name,hi,short,kw,price,dur,why,sam,faq=s
    sam_txt=", ".join(x.lower() for x in sam)
    k=slug
    return [
    (f"About {name} ({hi})",f"<p>{why} {short} Families choose this puja at important moments of life or when starting something new, and it is usually performed with the whole household present so that everyone takes part in the sankalp, aarti and prasad.</p><p>The details of the ritual can differ between regions, languages and family traditions, which is why we ask about your sampradaya at the time of booking. The pandit then follows the order of steps your family is used to rather than a single fixed script.</p>"),
    (f"When is {name} usually performed?",_pick(k,
     f"<p>There is no single date that suits every family. A pandit usually looks at the tithi, nakshatra, weekday and the family’s Panchang tradition, and also considers practical points such as the guests’ availability and the venue. For {name.lower()}, we recommend asking for muhurat options at least a week ahead, and earlier in wedding season or festival weeks, when pandit availability is tight.</p><p>If you do not have a date in mind, choose “help me find a date” in the form and give us a range of days. We will suggest the best muhurats for your city.</p>",
     f"<p>Most families fix the date with the help of a pandit or the family almanac and then plan guests and travel around it. Because sunrise and the tithi timings change from city to city, the same day can have a slightly different best hour in different places. We check the muhurat for your city before confirming {name.lower()}, and we respect the Panchang your family follows.</p><p>Book early for popular dates; a good muhurat on a weekend is the first to be taken.</p>")),
    ("How the puja usually flows",f"<p>The exact order depends on tradition, but {name.lower()} typically takes about {dur} and follows a pattern like this:</p><ol class='steps'><li><b>Sankalp:</b> the family states its names, gotra, place and purpose of the puja.</li><li><b>Ganesh puja and kalash sthapana:</b> invoking Lord Ganesh and the sacred water pot to remove obstacles.</li><li><b>Main puja:</b> worship of the central deity or ritual of the day with the correct mantras.</li><li><b>Havan or offering (where applicable):</b> offerings into the sacred fire with chanting.</li><li><b>Aarti and pushpanjali:</b> the family offers flowers and light together.</li><li><b>Prasad and dakshina:</b> prasad is shared and the pandit is honoured with dakshina.</li></ol>"),
    ("Samagri: what you need",f"<p>The usual samagri for {name.lower()} includes {sam_txt}. Fresh flowers, fruits and leaves are best bought on the morning of the puja. If you prefer not to arrange these yourself, choose the “with samagri” option and the pandit will bring a complete kit; the page shows both prices. If you are collecting items yourself, ask the pandit for a final list a day ahead so nothing is missed.</p>"),
    (f"How to prepare your home for {name}",f"<ul><li>Clean the space and keep a clean, level area ready, ideally facing east or north as your pandit advises.</li><li>Keep a low seat or mat for the pandit and enough seating for the family.</li><li>Keep names and gotra of family members ready for the sankalp.</li><li>For apartments, check if a havan or open flame is permitted and inform neighbours.</li><li>Keep drinking water, a place for the pandit to rest and containers for prasad.</li><li>Switch phones to silent and ask guests to arrive a little before the muhurat.</li></ul>"),
    ("Choosing a pandit: what to ask",f"<p>A good pandit explains what is being done and why, arrives on time, and respects the family’s tradition. When you book {name.lower()} through us you can ask about the language, how many years of experience the pandit has, whether the pandit brings the samagri and whether the pandit can explain the mantras in simple words. We confirm all this on WhatsApp before you pay. Our pandits do not pressure families into extra rituals; if something additional is genuinely recommended, it is explained first.</p>"),
    (f"Price and what affects it",f"<p>{name} starts from ₹{price:,} and usually takes about {dur}. The final price depends on the type and scale of the ritual, whether you want the samagri kit, how many pandits are needed, the distance to the venue and the date. We share a clear amount on WhatsApp before you pay, and dakshina is separate and at your discretion.</p>"),
    (f"Can {name} be done online?",f"<p>Yes, if you live abroad or the pandit cannot travel, a pandit can lead the puja by video, perform the sankalp in your name and gotra and guide you through each step. For many families, an online puja followed by sharing prasad with relatives works well. Ask us for the online option when booking.</p>"),
    ("Common mistakes to avoid","<ul><li>Booking too late for popular dates and festival weeks.</li><li>Fixing guests and venue before confirming the muhurat.</li><li>Not asking the pandit for the samagri list in advance.</li><li>Forgetting to tell the pandit the family tradition or language.</li><li>Assuming one ritual order fits every region.</li></ul>"),
    (f"Book {name} near you",f"<p>We arrange pandits in <a href=\"pandit-in-guwahati.html\">Guwahati</a>, <a href=\"pandit-in-kolkata.html\">Kolkata</a>, <a href=\"pandit-in-delhi.html\">Delhi</a>, <a href=\"pandit-in-mumbai.html\">Mumbai</a>, <a href=\"pandit-in-bengaluru.html\">Bengaluru</a>, <a href=\"pandit-in-chennai.html\">Chennai</a>, <a href=\"pandit-in-hyderabad.html\">Hyderabad</a> and <a href=\"locations.html\">many more cities</a>, and online across India. Pick your language from <a href=\"hindi-pandit.html\">Hindi</a>, <a href=\"bengali-pandit.html\">Bengali</a>, <a href=\"tamil-pandit.html\">Tamil</a> and others.</p>")]

def _sections_lang(path,l):
    nm,sc,w,eng,gp,tr=l
    cs=[x for x in CITYDATA if nm in STATES[x[2]][2]][:12]
    return [
    (f"Why a {nm}-speaking {eng.lower()} matters",f"<p>A puja is more than a sequence of mantras. When the {eng.lower()} explains the steps in {nm}, answers a grandmother’s question and follows the customs your family knows, everyone takes part instead of watching. That is why we match by language and sampradaya before anything else. {tr}</p>"),
    (f"What to expect from a {nm} puja",f"<p>A {nm}-speaking {eng.lower()} will usually chant the Sanskrit mantras and explain the meaning of key steps in {nm}, so younger family members understand what they are offering. The sankalp, in which the family states its names, gotra and purpose, is spoken clearly, and the sequence follows the {nm} tradition as far as your family follows it. If your family has its own customs, share them in advance.</p>"),
    (f"Popular pujas in {nm}","<ul>"+"".join(f'<li><a href="{s[0]}.html"><b>{s[1]}</b></a>: {s[3]} From ₹{s[5]:,}.</li>' for s in S[:8])+"</ul>"),
    (f"{gp}: {nm} Griha Pravesh",f"<p>{tr} We confirm the muhurat for your city and check the samagri before the day. Tell us the type of home, the date range and your family tradition and we do the rest.</p>"),
    ("Where we arrange pandits",f"<p>We arrange {nm}-speaking pandits in "+", ".join(f'<a href="pandit-in-{x[0]}.html">{x[1]}</a>' for x in cs)+(", and more cities" if cs else "")+f", and online anywhere in India. See all <a href=\"locations.html\">locations</a>.</p>"),
    ("How booking works","<ol class='steps'><li>Tell us the puja, date and language in the form or on WhatsApp.</li><li>We confirm a pandit and muhurat for your city.</li><li>You pay only after confirmation.</li><li>The pandit arrives on time with the puja plan, and with the samagri kit if you chose it.</li></ol>"),
    ("Online puja in "+nm,f"<p>If a {nm}-speaking {eng.lower()} is not free on your date or you live away from home, a pandit can lead the puja by video and perform the sankalp in your name. This works well for festival pujas, birthday homams, shraddh and griha pravesh when travel is not possible.</p>"),
    ("Samagri and cost",f"<p>Pujas start from ₹{min(x[5] for x in S):,}. Each puja page lists the samagri and shows the price with and without the kit. We confirm the final amount on WhatsApp before you pay. Dakshina is separate and up to you.</p>"),
    (f"Festivals where {nm} families book a pandit",f"<p>{nm}-speaking families commonly book a pandit for festival pujas, new beginnings and family milestones: griha pravesh, satyanarayan katha, annaprasan, mundan, seemantham and shraddh. Festival weeks are the busiest for pandits, so share your date early. Our <a href=\"festival-calendar-2026.html\">festival calendar</a> helps you plan, and the <a href=\"blog.html\">blog</a> explains dates and rules in simple words.</p>"),
    (f"Choosing the muhurat for a {nm} family","<p>The muhurat comes from the tithi, nakshatra and weekday, and from the Panchang your family follows. Regional calendars can differ by a day and local sunrise changes the timing from city to city, so we confirm the muhurat for your own city. If you have a date from your family priest, share it and we will confirm. If not, give us a range of days and we will suggest the best ones.</p>"),
    ("Tips for a smooth puja","<ul><li>Share your family tradition and gotra when you book.</li><li>Confirm the muhurat and arrival time a day before.</li><li>Keep names of all family members ready for the sankalp.</li><li>Check society rules if a havan is planned.</li><li>Book early in festival and wedding seasons.</li></ul>")]

def _sections_blog(path,a):
    slug,title,cat,desc,pat,intro,secs,svc=a
    sv=next(x for x in S if x[0]==svc)
    return [
    ("Key points to remember",f"<ul><li>Dates and timings for {cat.lower()} topics can differ by city and by Panchang tradition, so confirm with your pandit.</li><li>Follow your own family tradition; customs vary between regions and communities.</li><li>Plan early: popular dates and festival weeks fill pandit calendars quickly.</li><li>Prepare the samagri a day ahead and keep the names and gotra of the family ready.</li></ul>"),
    ("How to use this guide",f"<p>This guide on {title.lower().rstrip('?')} is meant as a practical starting point, not a replacement for the advice of your family priest. Read it to understand the meaning and sequence, then check the exact date, timing and rules for your city. If a detail differs from what your family follows, go with your tradition and ask your pandit to adapt the ritual accordingly.</p>"),
    ("Questions to ask your pandit",f"<ul><li>What is the best muhurat in our city for this?</li><li>Which steps will you explain in our language?</li><li>What samagri do we need, and can you bring a kit?</li><li>How long will it take, and how many people should attend?</li><li>What is the total price, and what is included?</li></ul>"),
    (f"Related puja: {sv[1]}",f"<p>If you want a pandit for this occasion, <a href=\"{sv[0]}.html\">{sv[1]}</a> is the closest ritual we arrange. {sv[7]} It starts from ₹{sv[5]:,} and takes about {sv[6]}. Samagri for it usually includes {', '.join(x.lower() for x in sv[8][:4])}.</p>"),
    ("Planning with the Panchang","<p>The Panchang is the Hindu almanac that lists the tithi, nakshatra, yoga and karana for each day. Local sunrise and moonrise change the effective timings from city to city, and regional calendars differ between solar and lunar traditions. That is why a festival can fall on different dates in different states and why we always confirm the date for your city.</p>"),
    ("Why local practice differs","<p>Hindu practice is not one uniform rulebook. Rituals, mantras, offerings and even the date of a festival vary between regions, languages and family lineages. A tradition followed in Assam may differ from one in Tamil Nadu, and both are valid for the families who follow them. When you read any guide, including this one, treat it as a general explanation and give priority to what your own elders and family priest practise.</p>"),
    ("Planning ahead","<p>Good planning removes most stress from a puja. Fix a range of dates, ask for the muhurat, confirm the pandit, arrange samagri a day before and keep names and gotra ready. If guests are travelling, share the muhurat with them early. For festivals, book earlier than usual because pandits are in high demand in those weeks.</p>"),
    ("Book a pandit",f"<p>Online Pujari arranges verified pandits in <a href=\"locations.html\">Indian cities</a> and online. Choose your puja, date and language, and we confirm the pandit and muhurat on WhatsApp before you pay. Browse <a href=\"services.html\">all pujas</a> or read more in our <a href=\"blog.html\">blog</a>.</p>"),
    ("Frequently asked questions","<h3>Are the dates the same everywhere in India?</h3><p>Not always. Regional calendars and local sunrise can shift a festival or vrat by a day, so check with your pandit.</p><h3>Can I perform the ritual myself?</h3><p>Many simple rituals can be done at home with guidance; a pandit helps with correct mantras and sequence.</p><h3>Can the puja be done online?</h3><p>Yes, a pandit can lead it by video and guide you step by step.</p>")]

def _sections_generic(path,title):
    lo=min(x[5] for x in S);hi=max(x[5] for x in S)
    return [
    ("How Online Pujari works",f"<p>Online Pujari is a pandit booking service for families across India. You choose the puja, the date and the language; we match a verified pandit, confirm the muhurat for your city on WhatsApp and take payment only after confirmation. The pandit arrives with a puja plan, and with the complete samagri kit if you chose that option. For families who cannot be present or cannot find a pandit locally, an online puja is available.</p>"),
    ("Pujas and sanskar we arrange",f"<p>We arrange {_pl(S[:10])} and more. Each page explains the purpose, the samagri, the typical duration and the starting price, so you can decide with full information. Prices start from ₹{lo:,} and go up to ₹{hi:,} or more for larger ceremonies.</p>"),
    ("Languages and traditions",f"<p>We match pandits by language and tradition: <a href=\"hindi-pandit.html\">Hindi</a>, <a href=\"bengali-pandit.html\">Bengali</a>, <a href=\"tamil-pandit.html\">Tamil</a>, <a href=\"telugu-pandit.html\">Telugu</a>, <a href=\"kannada-pandit.html\">Kannada</a>, <a href=\"marathi-pandit.html\">Marathi</a>, <a href=\"gujarati-pandit.html\">Gujarati</a> and <a href=\"malayalam-pandit.html\">Malayalam</a>. Please share your family’s sampradaya and gotra so the sankalp and sequence are right for your household.</p>"),
    ("Where we work",f"<p>We list pandit booking for {len(CITYDATA)+len(METROS)+max(len(_A()),4)}+ cities, from Guwahati, Kolkata and Delhi to Mumbai, Bengaluru, Chennai and Hyderabad. See the <a href=\"locations.html\">full list of locations</a>. If your town is not listed, message us; we may have a pandit nearby or can arrange an online puja.</p>"),
    ("Choosing the muhurat","<p>Muhurat is chosen from the tithi, nakshatra, weekday and your family’s Panchang tradition. Because local sunrise changes the timing from city to city, we confirm the muhurat for your own city. If you do not have a date, share a few days that suit you and we suggest the best options. Book at least a week ahead, and earlier for festival and wedding seasons.</p>"),
    ("Preparing for your puja","<ul><li>Clean the puja space and keep a low seat for the pandit.</li><li>Confirm the date, muhurat and arrival time on WhatsApp.</li><li>Arrange or confirm the samagri kit.</li><li>Keep names and gotra of family members ready.</li><li>Check society rules if a havan is planned.</li></ul>"),
    ("Pricing and payment",f"<p>Pujas start from ₹{lo:,}. The price depends on the ritual, duration, samagri and the number of pandits. We confirm the total on WhatsApp before you pay, and dakshina for the pandit is separate and at your discretion. Refund and cancellation rules are in our <a href=\"refund.html\">refund policy</a>.</p>"),
    ("Why families trust us","<p>We speak to every pandit before listing them, confirm the plan with you before payment, and keep the process transparent: a named pandit, a confirmed muhurat and a clear price. We do not publish invented reviews or statistics. If something goes wrong, you can reach us directly on WhatsApp or through the <a href=\"contact.html\">contact page</a>.</p>"),
    ("Respect for every tradition","<p>India’s traditions differ widely: a Bengali Lakshmi puja, a Tamil Ganapathi homam and a Gujarati vastu pujan share a spirit but not a script. We never push a single template. Our pandits follow the order your family is used to, explain each step in your language and adapt the ritual to the space available, whether that is a small flat, a society hall or a shop. If your family has its own customs, tell us and we will pass them on to the pandit before the day.</p>"),
    ("Privacy and safety","<p>We ask only for the details needed to arrange your puja: your name, phone number, city, date and puja type. We do not ask for ID numbers or bank passwords, and we never share your details for advertising. Payment is taken only after the pandit and muhurat are confirmed. Read our <a href=\"privacy.html\">privacy policy</a> and <a href=\"terms.html\">terms</a> for the full details.</p>"),
    ("Tips for first-time families","<p>If this is your first time arranging a puja, start by deciding the occasion and a range of dates, then ask us for the muhurat options. Speak to elders about family customs, and note the gotra and names of those taking part. Keep the puja space clean and simple, arrange fresh flowers and fruit on the morning of the puja and let the pandit guide the rest. The glossary and blog explain common words so that nothing feels unfamiliar on the day.</p>"),
    ("Frequently asked questions","<h3>How soon can I book?</h3><p>We try to help even at short notice, but a week ahead is best.</p><h3>Do I need to buy the samagri?</h3><p>No. Choose the kit option and the pandit brings it.</p><h3>Can I get a pandit in my language?</h3><p>Yes, pick the language in the form.</p><h3>Is an online puja valid?</h3><p>Many families find an online puja meaningful when travel is not possible; the pandit performs the sankalp in your name and guides you.</p>")]

_ST={"bengaluru":"karnataka","chennai":"tamil-nadu","hyderabad":"telangana","pune":"maharashtra","mumbai":"maharashtra"}
def _place(path):
    p=path[:-5]
    if p.startswith("pandit-in-") or p.startswith("pandit-ji-in-"):
        sl=p.replace("pandit-ji-in-","").replace("pandit-in-","")
        for c in CITYDATA:
            if c[0]==sl:
                s=STATES[c[2]];return dict(city=c[1],state=s[0],areas=c[3],sup=s[2],fest=s[3],note=s[4],reg=s[1],hub=f"pandits-in-{c[2]}.html")
        for m in METROS:
            if m[0]==sl:
                s=STATES[_ST[sl]];return dict(city=m[1],state=s[0],areas=m[3],sup=m[2],fest=s[3],note=m[4],reg=s[1],hub=f"pandits-in-{_ST[sl]}.html")
        for a in _A():
            if a[0]==p:
                return dict(city=a[1],state="Delhi NCR",areas=a[2],sup=["Hindi","Punjabi" if False else "Hindi","Bengali"][:1]+["Bengali"],fest="Diwali, Dussehra, Navratri, Karwa Chauth, Chhath and Janmashtami",note=a[3],reg="Hindi",hub="locations.html")
        if "noida" in sl:
            return dict(city="Noida and Greater Noida",state="Delhi NCR",areas="Sectors, Gaur City, Alpha, Beta and Pari Chowk",sup=["Hindi","Bengali"],fest="Diwali, Dussehra, Navratri, Karwa Chauth and Chhath",note="Noida and Greater Noida have many high-rise societies, so plan around society rules for havan and parking.",reg="Hindi",hub="locations.html")
    return None

FC=("<ul class='fcards' role='list'>"+"".join(f"<li class='fcard'><svg viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='1.8' stroke-linecap='round' stroke-linejoin='round' aria-hidden='true'><path d='{d}'/></svg><b>{t}</b><span>{x}</span></li>" for d,t,x in [("M12 3l8 3v6c0 5-3.5 8-8 9-4.5-1-8-4-8-9V6z M9 12l2 2 4-4","Verified pandits","We speak to every pandit before listing them."),("M12 21a9 9 0 1 0 0-18 9 9 0 0 0 0 18z M12 7v5l3 2","Muhurat confirmed","Timings checked for your own city and Panchang."),("M5 13l4 4L19 7","Pay after confirmation","Nothing is charged until the plan is confirmed."),("M12 21a9 9 0 1 0 0-18 9 9 0 0 0 0 18z M3 12h18 M12 3c3 3 3 15 0 18 M12 3c-3 3-3 15 0 18","Your language","Hindi, Bengali, Tamil, Telugu and more.")])+"</ul>")
def _sections_legal(path):
    p=path[:-5].split("/")[-1]
    common=[
    ("Who we are and what this page is for","<p>Online Pujari helps families across India and abroad find a verified pandit for pujas and sanskar, at home, in a society hall, at an office or shop, or online. This plain-language guide sits beside our formal policy to help you understand it quickly. It is an explanation, not a legal document: if any detail here ever differs from the policy text above, the policy text above applies.</p><p>We keep our language simple on purpose. Booking a puja is often an emotional and time-sensitive decision for a family, and you should never need a lawyer to understand what you are agreeing to.</p>"),
    ("How a booking works","<p>You choose a puja, a city, a date range and the language you prefer, using the booking form or WhatsApp. We then match a pandit, check the muhurat for your city and send you the plan on WhatsApp. You pay only after the pandit and muhurat are confirmed. Prices shown on the website are starting prices, and the final amount can vary with the city, the samagri you choose and the number of pandits needed. We confirm the total before you pay.</p><p>The pandits who perform your puja are independent professionals whom we connect you with. We take care to speak to every pandit before listing them and to confirm the plan with you, but the ritual itself is carried out by the pandit according to your family’s tradition.</p>"),
    ("The details we ask for, and why","<p>To arrange a puja we ask for your name, phone number, city, preferred date and puja type, plus your language and, if you wish, your gotra for the sankalp. We use these details only to arrange your booking and to contact you about it. We do not sell your data, and we do not ask for government ID numbers, bank passwords or card numbers through the website.</p><p>If you create an account, you sign in with Google. We store the name, email and phone number connected to your account so that you can see your bookings, and pandits can see the details of bookings assigned to them so they can reach you on time.</p>"),
    ("Your choices and how to reach us","<p>You can ask us to correct or delete the details we hold about you by messaging us on WhatsApp or through the contact page. You can also stop using the service at any time. If something about a booking, a payment or a pandit does not feel right, tell us straight away; we would rather fix it early than have you wait.</p><p>The website remembers one small preference in your own browser, your light or dark mode choice. It stays on your device and is not sent to us.</p>"),
    ("Respect for every tradition","<p>Hindu practice differs between regions, languages and family lineages. A Bengali Lakshmi puja, a Tamil Ganapathi homam and a Gujarati vastu pujan share a spirit but not a script. We do not push a single template. Please tell us your family’s sampradaya and customs when you book so that the pandit prepares the correct sankalp and sequence, and let us know if anything needs to be adapted for the space you have.</p>"),
    ("Dates, muhurat and festivals","<p>The auspicious time for a puja is chosen from the tithi, nakshatra, weekday and the almanac your family follows. Because local sunrise changes from one city to another, we confirm the muhurat for your own city. During festival weeks and wedding season pandits book out quickly, so we suggest asking at least a week ahead, and earlier for Diwali, Ganesh Chaturthi and Navratri. Our festival calendar lists the main dates, which follow the New Delhi panchang.</p>"),
    ("Common questions","<h3>Do I pay in advance?</h3><p>No. You pay after the pandit and muhurat are confirmed.</p><h3>Can I change the date?</h3><p>Yes. Please see the rescheduling terms in the policy above, and tell us as early as possible.</p><h3>What if a pandit is not available?</h3><p>If we cannot assign a pandit for your booking, you receive a full refund, as stated in the policy above.</p><h3>Is an online puja possible?</h3><p>Yes. A pandit can lead the puja by video and perform the sankalp in your name and gotra.</p><h3>Who do I contact with a problem?</h3><p>Message us on WhatsApp or use the contact page. We respond as quickly as we can.</p>"),
    ("Where to find more","<p>You can read about our <a href=\"services.html\">pujas and prices</a>, find a pandit in <a href=\"locations.html\">your city</a>, check <a href=\"festival-calendar-2026.html\">festival dates</a>, read our <a href=\"blog.html\">puja guides</a> or learn the terms in our <a href=\"puja-glossary.html\">puja glossary</a>. If you are a pandit and would like to join us, see <a href=\"become-a-pandit.html\">Become a pandit</a>.</p>")]
    spec={"privacy":[("What “privacy” means for a puja booking","<p>A puja booking involves personal details: where you live, your family’s names and sometimes your gotra and birth-related information. We treat these as private. We collect only what is needed to arrange your booking, we do not sell it, and we keep the process transparent. When a pandit is assigned to your booking, only the details needed for that puja are shared with that pandit, such as your name, phone, address and date.</p><p>If you sign in with Google, Google handles your password; we never see it. We rely on Google sign-in and a secure database to store your account details, and we limit who can read them.</p>"),("Security and children","<p>Access to our admin tools is limited to our team. Pandits see only the bookings assigned to them. Customers see only their own bookings. If you suspect misuse of your details, tell us immediately and we will look into it. Our service is meant for adults arranging pujas for their families; if a child’s details are needed, such as for a mundan or annaprasan, they should be given by a parent or guardian.</p>")],
    "terms":[("What you agree to when you book","<p>By booking you confirm that the details you give are correct and that you are authorised to arrange the puja at the address you provide. A booking is confirmed once the pandit and muhurat are agreed. We connect you with independent pandits and are not responsible for the outcome of rituals, which depend on faith, tradition and many factors outside our control.</p><p>Please be present at the venue at the agreed time, provide access, parking details and any society permissions, and tell us in advance about any restrictions such as a ban on open flame, so that the pandit can adapt.</p>"),("Prices, samagri and dakshina","<p>Prices on the website are starting prices. The final amount can vary with the puja, the city, the samagri kit and the number of pandits. Dakshina for the pandit and food or hospitality for guests are separate and are entirely up to you. We confirm the total before you pay, so there should be no surprises on the day.</p>")],
    "refund":[("Rescheduling and refunds in simple words","<p>If your plans change, tell us as early as you can. Rescheduling is free up to 48 hours before the puja. If we cannot assign a pandit for your booking, you receive a full refund. For anything else, such as cancellation close to the puja or a problem on the day, message us and we will discuss it with you fairly.</p><p>To help us resolve a request quickly, please share your name, phone number, the puja and date, and a short description of what happened.</p>"),("How to request a change or refund","<ol class=\"steps\"><li>Message us on WhatsApp or use the contact page.</li><li>Share your name, phone number, puja and date.</li><li>Tell us whether you want to reschedule or cancel.</li><li>We confirm the next step with you in writing.</li></ol>")]}
    return spec.get(p,[])+common

def seo_more(path,body):
    if path in SKIP or path.startswith("account"):return ""
    have=0
    secs=None
    if path in ("privacy.html","terms.html","refund.html"):secs=_sections_legal(path)
    elif path.startswith("pandits-in-"):
        st=path[len("pandits-in-"):-5]
        if st in STATES:
            s=STATES[st];secs=_sections_state(path,dict(state=s[0],cs=[c for c in CITYDATA if c[2]==st],sup=s[2],fest=s[3],note=s[4],reg=s[1]))
    elif path.startswith(("pandit-in-","pandit-ji-in-")):
        c=_place(path)
        if c:secs=_sections_city(path,c)
    elif path.endswith("-pandit.html") and path[:-12].title() in LN:
        secs=_sections_lang(path,LN[path[:-12].title()])
    else:
        sl=path[:-5]
        for s in S:
            if s[0]==sl:secs=_sections_puja(path,s)
        for a in ARTS:
            if a[0]==sl:secs=_sections_blog(path,a)
        if secs is None:secs=_sections_generic(path,"")
    if secs is not None and path not in ("privacy.html","terms.html","refund.html"):
        seen={h for h,_ in secs};secs=list(secs)+[x for x in _sections_generic(path,"") if x[0] not in seen and x[0]!="Frequently asked questions"]
    out=[];n=have
    for h,b in secs:
        out.append(f"<h2>{h}</h2>{b}");n+=_wc(f"<h2>{h}</h2>{b}")
        if n>=TARGET:break
    return '<section class="seo-more"><div class="w">'+FC+'<div class="prose">'+"".join(out)+"</div></div></section>"
